<?phpif (!defined('BASEPATH')) exit('No direct script access allowed');class mcadmodel extends CI_Model {    function fnGetcadrequirementInfo($VarCadrequirement='',$VarStatus='',$VarId='',$VarType='') {        $this->db->select('id,requirement,updatedby,status,datecreated,dateupdated');        $this->db->from(KN_CAD_REQUIREMENTPURPOSE);        if($VarStatus<>'') {            $this->db->where_in('status',array($VarStatus));        } else {            $this->db->where_in('status',array(1,2));        }        if($VarCadrequirement<>'') {            $ArrWhere['requirement'] 				    = $VarCadrequirement;        }        if($VarId<>'') {            $ArrWhere['id'] 				            = $VarId;        }        if($VarType<>'') {            $ArrWhere['type'] 		                    = $VarType;        }        if(@count($ArrWhere)>=1) {            $this->db->where($ArrWhere);        }        $ArrResultList	    	    		            = $this->db->get()->result_array();        return $ArrResultList;    }    function savecadrequirementInfo($ArrUpdateData) {        $VarId                                                  = $ArrUpdateData['id'];        $ArrCheckExist			       					    = $this->fnGetcadrequirementInfo($ArrUpdateData['requirement'],1);        if(isset($ArrCheckExist[0]['id'])) {            $ArrResult['errcode']						    = '-1';            $ArrResult['msg']							    = 'Already Exists';            $ArrResult['id']							    = $VarId;            $ArrResult['eid']							    = '';        }        else {            if ($VarId == "" && $VarId == 0) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_CAD_REQUIREMENTPURPOSE, $ArrUpdateData);                $VarId                = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg']     = '';                $ArrResult['id']      = $VarId;                $ArrResult['eid']     = urlencode(base64_encode($VarId));            } else {                if ($this->db->update(KN_CAD_REQUIREMENTPURPOSE, $ArrUpdateData, array('id' => $VarId))) {                    $ArrResult['errcode'] = 1;                    $ArrResult['msg']     = '';                    $ArrResult['id']      = $VarId;                    $ArrResult['eid']     = urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode'] = '-1';                    $ArrResult['msg']     = 'Invalid Data!';                }            }        }        return $ArrResult;    }    function fnCountRequirement($VarCadrequirement='',$VarStatus='',$VarAfilter='') {        $userInfo                   = fnGetUserLoggedInfo(1);        $ArrWhere                   = array();        if($VarCadrequirement<>'') {            $ArrWhere[]             = "c.requirement like '%".$VarCadrequirement."%'";        }        if($VarAfilter<>'') {            $ArrWhere[]             = "c.requirement LIKE '".$VarAfilter."%'";        }        if($VarStatus<>'') {            $ArrWhere[]             = "c.status=".$VarStatus;        } else {            $ArrWhere[]             = "c.status in(1,2)";        }        $ArrWhere[]                 = "c.companyid = ".$userInfo['companyid']." AND c.type = 1";        $VarWhere                   = '';        if(@$ArrWhere[0]<>'') {            $VarWhere               = implode(" and ",$ArrWhere);        }        $VarSqlLab              = "SELECT count(1) as trec  FROM ".KN_CAD_REQUIREMENTPURPOSE." AS c INNER JOIN ".KN_USERS." AS u ON c.updatedby = u.id WHERE ".$VarWhere;        $ObjRows					= $this->db->query($VarSqlLab)->row();        return $ObjRows->trec;    }    function fnListCadRequirement($VarRequirement='', $VarStatus='',$VarLimit = 10, $offset = 0,$VarSortBy,$VarSortOrder,$VarAfilter='') {        $userInfo                   = fnGetUserLoggedInfo(1);        $VarSortOrder				= ($VarSortOrder=='desc')? 'desc' : 'asc';        $VarSortCols				= array('c.status','u.contactname','c.dateupdated');        $VarSortBy					= (in_array($VarSortBy,$VarSortCols)) ? $VarSortBy : 'c.dateupdated';        $VarLimitInfo				= $VarLimit;        if($offset>=1) {$VarLimitInfo	 = $offset.",".$VarLimit;}        $ArrWhere                   = array();        if($VarRequirement<>'') {            $ArrWhere[]             = "c.requirement like '%".$VarRequirement."%'";        }        if($VarAfilter<>'') {            $ArrWhere[]             = "c.requirement LIKE '".$VarAfilter."%'";        }        if($VarStatus<>'') {            $ArrWhere[]             = "c.status=".$VarStatus;        } else {            $ArrWhere[]             = "c.status in(1,2)";        }        $ArrWhere[]                 = "c.companyid = ".$userInfo['companyid']." AND c.type = 1";        $VarWhere                   = '';        if(@$ArrWhere[0]<>'') {            $VarWhere               = implode(" and ",$ArrWhere) ;        }        $VarSqlLab                  = "SELECT c.id,c.requirement,u.contactname,c.datecreated,c.dateupdated,c.status FROM ".KN_CAD_REQUIREMENTPURPOSE." AS c INNER JOIN ".KN_USERS." AS u ON c.updatedby = u.id         WHERE ".$VarWhere." order by ".$VarSortBy." ".$VarSortOrder." limit ".$VarLimitInfo;        $ObjResult					= $this->db->query($VarSqlLab);        return $ObjResult;    }    function fnDel($VarId='',$VarUpdatedBy='') {        if(@$VarId>=1) {            $ArrUpdateData          = array('status'=>3,'dateupdated'=>date('Y-m-d H:i:s'),'updatedby'=>$VarUpdatedBy);            if($this->db->update(KN_MASTER_BOM,$ArrUpdateData,array('id'=>$VarId,'type'=>'1'))) {                $ArrResult['errcode']					    = 1;                $ArrResult['msg']							= '';                $ArrResult['id']							= $VarId;                $ArrResult['eid']							= urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode']						= '-1';                $ArrResult['msg']							= 'Invalid Data!';            }        }        return $ArrResult;    }    function fnChangeComStat($checkboxids,$optvalue) {        $Arrids =  json_decode($checkboxids,true);        $this->db->where_in('id',$Arrids);        if($this->db->update(KN_MASTER_BOM,array('status' => $optvalue))) {            return true;        }        return false;    }    /**************************************************************************** PURPOSE ****************************************************************************/    function fnGetcadpurposeinfo($VarCadpurpose='',$VarStatus='',$VarId='',$VarType='') {        $this->db->select('id,purpose,updatedby,status,datecreated,dateupdated');        $this->db->from(KN_CAD_REQUIREMENTPURPOSE);        if($VarStatus<>'') {            $this->db->where_in('status',array($VarStatus));        } else {            $this->db->where_in('status',array(1,2));        }        if($VarCadpurpose<>'') {            $ArrWhere['purpose'] 				    = $VarCadpurpose;        }        if($VarId<>'') {            $ArrWhere['id'] 				            = $VarId;        }        if($VarType<>'') {            $ArrWhere['type'] 		                    = $VarType;        }        if(@count($ArrWhere)>=1) {            $this->db->where($ArrWhere);        }        $ArrResultList	    	    		            = $this->db->get()->result_array();        return $ArrResultList;    }    function fnCountPurpose($VarCadpurpose='',$VarStatus='',$VarType = '',$VarAfilter='') {        $userInfo                   = fnGetUserLoggedInfo(1);        $ArrWhere                   = array();        if($VarCadpurpose<>'') {            $ArrWhere[]             = "c.purpose like '%".$VarCadpurpose."%'";        }        if($VarAfilter<>'') {            $ArrWhere[]             = "c.purpose LIKE '".$VarAfilter."%'";        }        if($VarStatus<>'') {            $ArrWhere[]             = "c.status=".$VarStatus;        } else {            $ArrWhere[]             = "c.status in(1,2)";        }        $ArrWhere[]                 = "c.companyid = ".$userInfo['companyid']." AND c.type = ".$VarType;        $VarWhere                   = '';        if(@$ArrWhere[0]<>'') {            $VarWhere               = implode(" and ",$ArrWhere);        }        $VarSqlLab              = "SELECT count(1) as trec  FROM ".KN_CAD_REQUIREMENTPURPOSE." AS c INNER JOIN ".KN_USERS." AS u ON c.updatedby = u.id WHERE ".$VarWhere;        $ObjRows					= $this->db->query($VarSqlLab)->row();        return $ObjRows->trec;    }    function fnListCadPurpose($VarCadpurpose='', $VarStatus='',$VarType='',$VarLimit = 10, $offset = 0,$VarSortBy,$VarSortOrder,$VarAfilter='') {        $userInfo                   = fnGetUserLoggedInfo(1);        $VarSortOrder				= ($VarSortOrder=='desc')? 'desc' : 'asc';        $VarSortCols				= array('c.purpose','c.status','u.contactname','c.dateupdated');        $VarSortBy					= (in_array($VarSortBy,$VarSortCols)) ? $VarSortBy : 'c.dateupdated';        $VarLimitInfo				= $VarLimit;        if($offset>=1) {$VarLimitInfo	 = $offset.",".$VarLimit;}        $ArrWhere                   = array();        if($VarCadpurpose<>'') {            $ArrWhere[]             = "c.purpose like '%".$VarCadpurpose."%'";        }        if($VarAfilter<>'') {            $ArrWhere[]             = "c.purpose LIKE '".$VarAfilter."%'";        }        if($VarStatus<>'') {            $ArrWhere[]             = "c.status=".$VarStatus;        } else {            $ArrWhere[]             = "c.status in(1,2)";        }        $ArrWhere[]                 = "c.companyid = ".$userInfo['companyid']." AND c.type = ".$VarType;        $VarWhere                   = '';        if(@$ArrWhere[0]<>'') {            $VarWhere               = implode(" and ",$ArrWhere) ;        }        $VarSqlLab                  = "SELECT c.id,c.purpose,u.contactname,c.datecreated,c.dateupdated,c.status FROM ".KN_CAD_REQUIREMENTPURPOSE." AS c INNER JOIN ".KN_USERS." AS u ON c.updatedby = u.id         WHERE ".$VarWhere." order by ".$VarSortBy." ".$VarSortOrder." limit ".$VarLimitInfo;        $ObjResult					= $this->db->query($VarSqlLab);        return $ObjResult;    }    function savecadpurposeInfo($ArrUpdateData) {        $VarId                                              = $ArrUpdateData['id'];        $ArrCheckExist			       					    = $this->fnGetcadpurposeinfo($ArrUpdateData['purpose'],1,'',2);        if(isset($ArrCheckExist[0]['id'])) {            $ArrResult['errcode']						    = '-1';            $ArrResult['msg']							    = 'Already Exists';            $ArrResult['id']							    = $VarId;            $ArrResult['eid']							    = '';        }        else {            if ($VarId == "" && $VarId == 0) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_CAD_REQUIREMENTPURPOSE, $ArrUpdateData);                $VarId                = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg']     = '';                $ArrResult['id']      = $VarId;                $ArrResult['eid']     = urlencode(base64_encode($VarId));            } else {                if ($this->db->update(KN_CAD_REQUIREMENTPURPOSE, $ArrUpdateData, array('id' => $VarId))) {                    $ArrResult['errcode'] = 1;                    $ArrResult['msg']     = '';                    $ArrResult['id']      = $VarId;                    $ArrResult['eid']     = urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode'] = '-1';                    $ArrResult['msg']     = 'Invalid Data!';                }            }        }        return $ArrResult;    }    function fnDelCadPurpose($VarId='',$VarUpdatedBy='') {        if(@$VarId>=1) {            $ArrUpdateData          = array('status'=>3,'dateupdated'=>date('Y-m-d H:i:s'),'updatedby'=>$VarUpdatedBy);            if($this->db->update(KN_MASTER_BOM,$ArrUpdateData,array('id'=>$VarId,'type'=>'1'))) {                $ArrResult['errcode']					    = 1;                $ArrResult['msg']							= '';                $ArrResult['id']							= $VarId;                $ArrResult['eid']							= urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode']						= '-1';                $ArrResult['msg']							= 'Invalid Data!';            }        }        return $ArrResult;    }}